begin;
-- Shared independent catalog, never a Google Places response cache or user-owned table.
create table public.places (
 city text not null check (city ~ '^[a-z]{2,80}$'),
 place_id text not null check (char_length(place_id) between 1 and 120),
 payload jsonb not null check (jsonb_typeof(payload) = 'object' and payload->>'place_id' = place_id),
 google_place_id text check (char_length(google_place_id) <= 255),
 source_urls jsonb not null default '[]' check (jsonb_typeof(source_urls) = 'array'),
 reviewed_at date,
 published boolean not null default false,
 updated_at timestamptz not null default now(),
 primary key (city, place_id),
 check (reviewed_at is null or jsonb_array_length(source_urls) > 0)
);
alter table public.places enable row level security;
alter table public.places force row level security;
revoke all on public.places from public, anon, authenticated;
grant select on public.places to anon, authenticated;
create policy published_place_catalog on public.places for select to anon, authenticated using (published);
comment on column public.places.payload is 'Independent curated planner facts only. No restricted Google response payloads, ratings, photos or reviews.';
